#!/usr/bin/env python3
"""Generate a local procedural texture pack without importing third-party imagery."""

import argparse
import os
from pathlib import Path
import subprocess
import sys
import tarfile
import tempfile

ROOT = Path(__file__).resolve().parents[1]
BODIES = ("earth", "moon", "mars", "mercury", "venus", "jupiter", "saturn", "uranus", "neptune")
CREDITS = (
    "# Procedural texture pack\n\n"
    "These maps were generated by Kosmos tools/gen_textures.py. "
    "They are fictional approximations, not maps of real surface features. "
    "They do not contain the optional Orbiter or Celestia imagery.\n"
)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path, help="new .tar.gz file")
    parser.add_argument("--scale", type=int, default=4,
                        help="divide the generator's default widths by this value (default: 4)")
    args = parser.parse_args()
    if args.scale < 1 or args.scale & (args.scale - 1) or args.scale > 32:
        parser.error("--scale must be a power of two between 1 and 32")
    output = args.output.resolve()
    if not output.name.endswith(".tar.gz"):
        parser.error("output must end in .tar.gz")
    if output.exists():
        parser.error("output already exists")
    if not output.parent.is_dir():
        parser.error("output directory does not exist")
    env = os.environ.copy()
    env.update(OPENBLAS_NUM_THREADS="1", MKL_NUM_THREADS="1", OMP_NUM_THREADS="1")
    with tempfile.TemporaryDirectory(prefix="kosmos-procedural-pack-") as directory:
        root = Path(directory)
        textures = root / "data/textures-generated"
        textures.mkdir(parents=True)
        subprocess.run([sys.executable, str(ROOT / "tools/gen_textures.py"), "--out", str(textures),
                        "--scale", str(args.scale), *BODIES], check=True, env=env)
        (textures / "CREDITS.md").write_text(CREDITS, encoding="utf-8")
        # Exclusive creation keeps an existing archive intact. A failed write is
        # left visible for inspection and must not be used as a release input.
        with output.open("xb") as file:
            with tarfile.open(fileobj=file, mode="w:gz") as archive:
                archive.add(textures, arcname="data/textures-generated")
    print(f"Created {output}; these procedural maps are not geographically accurate.")


if __name__ == "__main__":
    main()
